/**
 * Translation parity: Phue\Core\t() vs the client runtime.
 *
 * The fixture is GENERATED BY PHP — every `expected` value is the literal
 * string that `Translator::t()` returns for that exact (locale, message,
 * params) triple. This suite runs the same triples through the browser
 * implementation and demands a byte-identical result.
 *
 * That is what makes "works EXACTLY like the framework" mechanical instead of
 * aspirational: when a PHP change alters translation semantics, the PHP test
 * that regenerates the fixture fails first, and this file points straight at
 * the divergence.
 *
 * Run: node tests/Core/UI/runtime/i18n.parity.test.mjs
 */

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import assert from "node:assert/strict";

import { substitute, phueT } from "../../../../src/Core/UI/runtime/i18n.js";

const here = dirname(fileURLToPath(import.meta.url));
const fixture = JSON.parse(
    readFileSync(join(here, "parity-fixture.json"), "utf8")
);

/** Install a catalogue snapshot the way HtmlShellRenderer does in the browser. */
function withSnapshot(snapshot, fn) {
    const previous = globalThis.__PHUE_I18N__;
    globalThis.__PHUE_I18N__ = snapshot;
    try {
        return fn();
    } finally {
        globalThis.__PHUE_I18N__ = previous;
    }
}

let passed = 0;
const failures = [];

// Each case is generated for its own locale, so the flattened snapshot the
// server would send for that locale is rebuilt here from the same chain rules:
// most specific catalogue first, falling back to the default locale, then to
// the source message itself.
const catalogues = {
    el: {
        "Hello {name}": "Γεια {name}",
        Save: "Αποθήκευση",
        "{n} items": "{n} στοιχεία",
        Weird: "$& {x} %s",
        Nulled: "τύπος {v}",
    },
    de: {
        Save: "Speichern",
        "Only de": "Nur de",
    },
    en: {
        Fallback: "FB",
        Nulled: "type {v}",
    },
};

for (const testCase of fixture) {
    const label = `${testCase.locale} :: ${testCase.message}`;
    try {
        // `el` does not define "Only de" or "Fallback"; the default locale
        // `en` is consulted next, exactly as Translator::chain() does.
        const messages = {
            ...catalogues.en,
            ...(catalogues[testCase.locale] ?? {}),
        };

        const actual = withSnapshot(
            { locale: testCase.locale, messages },
            () => phueT(testCase.message, testCase.params ?? {})
        );

        assert.equal(
            actual,
            testCase.expected,
            `PHP produced ${JSON.stringify(testCase.expected)} but the client produced ${JSON.stringify(actual)}`
        );
        passed += 1;
    } catch (error) {
        failures.push({ label, message: error.message });
    }
}

// --- Guards for the JS traps the fixture cannot express ---------------------

// An absent snapshot must degrade to the source message, never throw. A raw
// PHP page, or a stale cached bundle, must not take a page down.
for (const snapshot of [undefined, null, {}, { messages: null }, { messages: "nope" }]) {
    try {
        const previous = globalThis.__PHUE_I18N__;
        globalThis.__PHUE_I18N__ = snapshot;
        assert.equal(phueT("Plain message"), "Plain message");
        assert.equal(phueT("With {x}", { x: "v" }), "With v");
        globalThis.__PHUE_I18N__ = previous;
        passed += 1;
    } catch (error) {
        failures.push({ label: `degrade(snapshot=${JSON.stringify(snapshot)})`, message: error.message });
    }
}

// An empty catalogue entry is a MISS, not a translation: Translator::catalog()
// drops empty strings so the chain falls through to the next locale. The
// snapshot is already flattened, so the client must honour the same rule.
try {
    const out = withSnapshot({ locale: "el", messages: { Empty: "" } }, () => phueT("Empty"));
    assert.equal(out, "Empty");
    passed += 1;
} catch (error) {
    failures.push({ label: "empty translation falls through", message: error.message });
}

// `$&` is a JS replacement metacharacter. If substitute() ever regresses to a
// string replacer, this is the assertion that catches it.
try {
    assert.equal(substitute("a $& b {v}", { v: "$&" }), "a $& b $&");
    passed += 1;
} catch (error) {
    failures.push({ label: "replacement metacharacters are literal", message: error.message });
}

// Every occurrence is replaced, not just the first (PHP strtr replaces all).
try {
    assert.equal(substitute("{x} and {x}", { x: "1" }), "1 and 1");
    passed += 1;
} catch (error) {
    failures.push({ label: "all occurrences replaced", message: error.message });
}

// --- Report ----------------------------------------------------------------

console.log(`i18n parity: ${passed} passed, ${failures.length} failed`);
for (const failure of failures) {
    console.error(`  FAIL ${failure.label}\n       ${failure.message}`);
}
process.exit(failures.length === 0 ? 0 : 1);